 public static class ElectricGaze {
  public static readonly string[] Modes={"characters","dither","mosaic","pixel","dots","cross","diamond","voxel","lego","mixed","lines","diagonal","braille","disco","hexdump","matrix","rings","hearts","stars","hexagons","triangles","bubbles","hatch","contour","halfblocks"};
  static double Clamp(double value){return Math.Max(0,Math.Min(1,value));}static byte Byte(double value){return (byte)Math.Max(0,Math.Min(255,value));}
  static double Hash(int x,int y,int seed){unchecked{uint n=(uint)(x*374761393+y*668265263+seed*1274126177);n=(n^(n>>13))*1274126177;return (n^(n>>16))/(double)uint.MaxValue;}}
  static Color Hex(string value){try{return ColorTranslator.FromHtml(value);}catch{return Color.FromArgb(60,166,255);}}
  static Bitmap Canvas(int w,int h){return new Bitmap(w,h,PixelFormat.Format32bppArgb);}
  static byte[] Pixels(Bitmap image){var data=image.LockBits(new Rectangle(0,0,image.Width,image.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var pixels=new byte[image.Width*image.Height*4];for(int y=0;y<image.Height;y++)Marshal.Copy(IntPtr.Add(data.Scan0,y*data.Stride),pixels,y*image.Width*4,image.Width*4);return pixels;}finally{image.UnlockBits(data);}}
  static void Put(Bitmap image,byte[] pixels){var data=image.LockBits(new Rectangle(0,0,image.Width,image.Height),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{for(int y=0;y<image.Height;y++)Marshal.Copy(pixels,y*image.Width*4,IntPtr.Add(data.Scan0,y*data.Stride),image.Width*4);}finally{image.UnlockBits(data);}}
  static double Curve(double l,List<CurvePoint> points){if(points==null||points.Count<2)return l;var p=points.OrderBy(a=>a.x).ToArray();for(int i=1;i<p.Length;i++)if(l<=p[i].x){double width=p[i].x-p[i-1].x;return Clamp(p[i-1].y+(p[i].y-p[i-1].y)*(width<=0?0:(l-p[i-1].x)/width));}return Clamp(p[p.Length-1].y);}
  static double Animation(GazeSettings s,int x,int y,double time,int w,int h){if(!s.animated&&s.renderMode!="matrix")return 0;double speed=s.animSpeed!=null&&s.animSpeed.enabled?s.animSpeed.intensity/100:0;double amp=s.animIntensity!=null&&s.animIntensity.enabled?s.animIntensity.intensity/100:0;double t=time*(.3+speed*2);switch(s.animStyle){case "wave":return Math.Sin(t*3+x*.09+y*.025)*amp*.16;case "pulse":return Math.Sin(t*3)*amp*.14;case "ripple":return Math.Sin(Math.Sqrt(Math.Pow(x-w*.5,2)+Math.Pow(y-h*.5,2))*.07-t*4)*amp*.18;case "flicker":return (Hash(x,y,(int)(t*10))-.5)*amp*.3;default:return (Math.Sin(x*.8+y*.13+t*3)+Math.Cos(y*.7-t*2))*amp*.07;}}
  public static Bitmap Render(Image source,int width,int height,GazeSettings settings,double time){if(source==null)throw new ArgumentNullException("source");if(!Modes.Contains(settings.renderMode))throw new Exception("Unknown raster mode");int w=Math.Max(8,Math.Min(1600,width)),h=Math.Max(8,Math.Min(1600,height));var plain=Canvas(w,h);using(var g=Graphics.FromImage(plain)){g.Clear(Color.Black);g.InterpolationMode=InterpolationMode.HighQualityBicubic;double scale=Math.Max(w/(double)source.Width,h/(double)source.Height);float sw=(float)(source.Width*scale),sh=(float)(source.Height*scale);g.DrawImage(source,(w-sw)/2,(h-sh)/2,sw,sh);}var effect=Canvas(w,h);using(var g=Graphics.FromImage(effect)){g.Clear(Color.Transparent);if(settings.bgMode!="none"){if(settings.bgMode=="solid"){using(var b=new SolidBrush(Color.FromArgb(Byte(settings.bgOpacity*2.55),Hex(settings.tint))))g.FillRectangle(b,0,0,w,h);}else{using(var background=(Bitmap)plain.Clone()){if(settings.bgMode=="blur"||settings.bgMode=="blurred")Blur(background,Math.Min(18,(int)settings.bgBlur));DrawOpacity(g,background,settings.bgOpacity/100);}}}}
   var px=Pixels(plain);int cell=Math.Max(2,Math.Min(60,settings.cellSize));int cols=(w+cell-1)/cell,rows=(h+cell-1)/cell;var lum=new double[cols,rows];var colors=new Color[cols,rows];var halfLum=new double[cols,rows*2];for(int cy=0;cy<rows;cy++)for(int cx=0;cx<cols;cx++){long r=0,green=0,b=0;int count=0;for(int y=cy*cell;y<Math.Min(h,(cy+1)*cell);y++)for(int x=cx*cell;x<Math.Min(w,(cx+1)*cell);x++){int i=(y*w+x)*4;b+=px[i];green+=px[i+1];r+=px[i+2];count++;}Color c=Color.FromArgb((int)(r/count),(int)(green/count),(int)(b/count));colors[cx,cy]=c;lum[cx,cy]=(.2126*c.R+.7152*c.G+.0722*c.B)/255;}
   if(settings.renderMode=="halfblocks")for(int cy=0;cy<rows;cy++)for(int cx=0;cx<cols;cx++)for(int part=0;part<2;part++){double sum=0;int count=0;int y0=cy*cell+(part==0?0:cell/2),y1=Math.Min(h,cy*cell+(part==0?cell/2:cell));for(int yy=y0;yy<y1;yy++)for(int xx=cx*cell;xx<Math.Min(w,(cx+1)*cell);xx++){int i=(yy*w+xx)*4;sum+=(.2126*px[i+2]+.7152*px[i+1]+.0722*px[i])/255;count++;}halfLum[cx,cy*2+part]=count==0?0:sum/count;}
   using(var g=Graphics.FromImage(effect))using(var font=new Font("Consolas",cell,FontStyle.Regular,GraphicsUnit.Pixel)){g.SmoothingMode=SmoothingMode.None;g.TextRenderingHint=TextRenderingHint.SingleBitPerPixelGridFit;for(int cy=0;cy<rows;cy++)for(int cx=0;cx<cols;cx++){if(Hash(cx,cy,71)*100>settings.coverage)continue;double l=Curve(lum[cx,cy],settings.toneCurve);if(settings.invert)l=1-l;double edge=Math.Abs(lum[cx,cy]-lum[Math.Max(0,cx-1),cy])+Math.Abs(lum[cx,cy]-lum[cx,Math.Max(0,cy-1)]);l=Clamp(l+edge*settings.edgeEmphasis/100+Animation(settings,cx*cell,cy*cell,time,w,h));Color color=colors[cx,cy];if(settings.invert)color=Color.FromArgb(255-color.R,255-color.G,255-color.B);DrawCell(g,cx,cy,cell,l,color,settings,time,font,lum,rows,halfLum);}}
   if(settings.styleBlend!="source-over"){var e=Pixels(effect);for(int i=0;i<e.Length;i+=4)for(int c=0;c<3;c++)e[i+c]=Byte(Blend(px[i+c]/255.0,e[i+c]/255.0,settings.styleBlend)*255);Put(effect,e);}
   Adjust(effect,settings);ApplyBlur(effect,settings);Post(effect,settings,time);Lights(effect,settings);Reveal(effect,plain,settings);plain.Dispose();return effect;
  }
  static void DrawOpacity(Graphics g,Image image,double opacity){using(var attrs=new ImageAttributes()){var matrix=new ColorMatrix();matrix.Matrix33=(float)Clamp(opacity);attrs.SetColorMatrix(matrix);g.DrawImage(image,new Rectangle(0,0,image.Width,image.Height),0,0,image.Width,image.Height,GraphicsUnit.Pixel,attrs);}}
  static void Polygon(Graphics g,Brush brush,float centerX,float centerY,float radius,int sides,double rotation){var points=Enumerable.Range(0,sides).Select(i=>new PointF(centerX+radius*(float)Math.Cos(rotation+2*Math.PI*i/sides),centerY+radius*(float)Math.Sin(rotation+2*Math.PI*i/sides))).ToArray();g.FillPolygon(brush,points);}
  static void DrawCell(Graphics g,int cx,int cy,int size,double l,Color color,GazeSettings s,double time,Font font,double[,] sourceLum,int rows,double[,] halfLum){float x=cx*size,y=cy*size,midX=x+size/2f,midY=y+size/2f;float radius=(float)(Math.Sqrt(l)*size*.48*(.55+s.density/200));string mode=s.renderMode;if(mode=="mixed")mode=new[]{"dots","cross","diamond","characters"}[(int)(Hash(cx,cy,9)*4)%4];using(var brush=new SolidBrush(color))using(var pen=new Pen(color,Math.Max(1,size/10f))){switch(mode){
   case "characters":case "hexdump":case "braille":case "matrix":{
    string chars=s.charSet=="custom"&&!string.IsNullOrEmpty(s.customChars)?s.customChars:s.charSet=="blocks"?" ░▒▓█":s.charSet=="binary"?" 01":" .:-=+*#%@";string glyph;if(mode=="hexdump")glyph="0123456789ABCDEF"[(int)(l*15)].ToString();else if(mode=="braille")glyph=char.ConvertFromUtf32(0x2800+(int)(l*255));else if(mode=="matrix"){double head=(time*9+Hash(cx,0,15)*rows*2)%(rows+12),tail=(head-cy+rows+12)%(rows+12);if(tail>12)return;glyph="01アイウエオカキクケコ"[(int)(Hash(cx,cy,(int)(time*6))*12)%12].ToString();brush.Color=Color.FromArgb(0,Byte((1-tail/13)*255),Byte((1-tail/13)*95));}else glyph=chars[(int)(Clamp(l)* (chars.Length-1))].ToString();g.DrawString(glyph,font,brush,x,y-1,StringFormat.GenericTypographic);break;}
   case "dither":{int step=Math.Max(1,size/3);double level=Clamp(l*(.7+s.density/200));for(int yy=0;yy<size;yy+=step)for(int xx=0;xx<size;xx+=step){int bayer=((xx/step&1)*2+(yy/step&1))*4+((xx/step/2&1)*2+(yy/step/2&1));double threshold=(bayer+.5)/16;if(level>threshold)g.FillRectangle(brush,x+xx,y+yy,Math.Max(1,step-1),Math.Max(1,step-1));}break;}
   case "mosaic":g.FillRectangle(brush,x,y,size-1,size-1);break;
   case "pixel":g.FillRectangle(brush,midX-radius,midY-radius,radius*2,radius*2);break;
   case "dots":g.FillEllipse(brush,midX-radius,midY-radius,radius*2,radius*2);break;
   case "cross":g.DrawLine(pen,midX-radius,midY,midX+radius,midY);g.DrawLine(pen,midX,midY-radius,midX,midY+radius);break;
   case "diamond":Polygon(g,brush,midX,midY,radius,4,0);break;
   case "voxel":{g.FillRectangle(brush,x,y,size-1,size-1);using(var dark=new SolidBrush(Color.FromArgb(80,0,0,0)))g.FillPolygon(dark,new[]{new PointF(x,y+size),new PointF(x+size,y+size),new PointF(x+size*.8f,y+size*.7f),new PointF(x+size*.2f,y+size*.7f)});break;}
   case "lego":g.FillRectangle(brush,x,y,size-1,size-1);using(var light=new Pen(Color.FromArgb(100,255,255,255)))g.DrawEllipse(light,x+size*.2f,y+size*.2f,size*.6f,size*.6f);break;
   case "lines":pen.Width=Math.Max(1,(float)(l*size*.55));g.DrawLine(pen,x,midY,x+size,midY);break;
   case "diagonal":g.DrawLine(pen,midX-radius,midY+radius,midX+radius,midY-radius);break;
   case "disco":{Color c=FromHue((cx*.03+cy*.04+time*.08)%1,l);using(var b=new SolidBrush(c))g.FillEllipse(b,midX-radius,midY-radius,radius*2,radius*2);break;}
   case "rings":g.DrawEllipse(pen,midX-radius,midY-radius,radius*2,radius*2);if(l>.55)g.DrawEllipse(pen,midX-radius*.5f,midY-radius*.5f,radius,radius);break;
   case "hearts":{using(var path=new GraphicsPath()){path.AddBezier(midX,midY+radius,midX-radius*2,midY-radius*.2f,midX-radius*.6f,midY-radius*1.8f,midX,midY-radius*.4f);path.AddBezier(midX,midY-radius*.4f,midX+radius*.6f,midY-radius*1.8f,midX+radius*2,midY-radius*.2f,midX,midY+radius);g.FillPath(brush,path);}break;}
   case "stars":{var points=Enumerable.Range(0,10).Select(i=>{float r=i%2==0?radius:radius*.4f;double a=i*Math.PI/5-Math.PI/2;return new PointF(midX+r*(float)Math.Cos(a),midY+r*(float)Math.Sin(a));}).ToArray();g.FillPolygon(brush,points);break;}
   case "hexagons":Polygon(g,brush,midX+(cy%2)*size*.5f,midY,radius,6,Math.PI/6);break;
   case "triangles":Polygon(g,brush,midX,midY,radius*1.2f,3,(cx+cy)%2==0?-Math.PI/2:Math.PI/2);break;
   case "bubbles":g.DrawEllipse(pen,midX-radius,midY-radius,radius*2,radius*2);if(radius>1)g.DrawArc(Pens.White,midX-radius*.65f,midY-radius*.65f,radius,radius,195,60);break;
   case "hatch":for(int k=0;k<(int)(l*5);k++){float off=k*size/5f;g.DrawLine(pen,x+off,y+size,x+size,y+off);if(l>.5)g.DrawLine(pen,x,y+off,x+size-off,y+size);}break;
   case "contour":{double a=sourceLum[cx,cy],b=sourceLum[Math.Max(0,cx-1),cy],c=sourceLum[cx,Math.Max(0,cy-1)];for(int k=1;k<7;k++){double t=k/7.0;if((a>=t)!=(b>=t))g.DrawLine(pen,x,midY,x+size,midY);if((a>=t)!=(c>=t))g.DrawLine(pen,midX,y,midX,y+size);}break;}
   case "halfblocks":{float half=size/2f;double upper=halfLum[cx,cy*2],lower=halfLum[cx,cy*2+1];using(var up=new SolidBrush(Color.FromArgb(Byte(upper*255),color)))g.FillRectangle(up,x,y,size,half);using(var down=new SolidBrush(Color.FromArgb(Byte(lower*255),color)))g.FillRectangle(down,x,y+half,size,half);break;}
  }}}
  static Color FromHue(double h,double l){double a=h*6;int sector=(int)a;double f=a-sector;double r=0,g=0,b=0;switch(sector%6){case 0:r=1;g=f;break;case 1:r=1-f;g=1;break;case 2:g=1;b=f;break;case 3:g=1-f;b=1;break;case 4:r=f;b=1;break;case 5:r=1;b=1-f;break;}return Color.FromArgb(Byte(r*l*255),Byte(g*l*255),Byte(b*l*255));}
  static double Blend(double source,double tint,string mode){switch(mode){case "multiply":return source*tint;case "screen":return 1-(1-source)*(1-tint);case "overlay":return source<.5?2*source*tint:1-2*(1-source)*(1-tint);case "difference":return Math.Abs(source-tint);case "lighten":return Math.Max(source,tint);case "darken":return Math.Min(source,tint);case "color-dodge":return tint>=1?1:Math.Min(1,source/(1-tint));default:return tint;}}
  static void Adjust(Bitmap image,GazeSettings s){byte[] p=Pixels(image);Color tint=Hex(s.tint);double factor=Math.Max(0,1+s.contrast/100),sat=Math.Max(0,s.saturation/100),gray=Clamp(s.grayscale/100),opacity=Clamp(s.tintOpacity/100);for(int i=0;i<p.Length;i+=4){double r=Clamp(p[i+2]/255.0+s.brightness/100),g=Clamp(p[i+1]/255.0+s.brightness/100),b=Clamp(p[i]/255.0+s.brightness/100);r=Clamp((r-.5)*factor+.5);g=Clamp((g-.5)*factor+.5);b=Clamp((b-.5)*factor+.5);double l=.2126*r+.7152*g+.0722*b;r=Clamp(l+(r-l)*sat);g=Clamp(l+(g-l)*sat);b=Clamp(l+(b-l)*sat);l=.2126*r+.7152*g+.0722*b;r=r*(1-gray)+l*gray;g=g*(1-gray)+l*gray;b=b*(1-gray)+l*gray;r=r*(1-opacity)+Blend(r,tint.R/255.0,s.overlayBlend)*opacity;g=g*(1-opacity)+Blend(g,tint.G/255.0,s.overlayBlend)*opacity;b=b*(1-opacity)+Blend(b,tint.B/255.0,s.overlayBlend)*opacity;p[i]=Byte(b*255);p[i+1]=Byte(g*255);p[i+2]=Byte(r*255);}Put(image,p);}
  static void Blur(Bitmap image,int radius){radius=Math.Min(24,Math.Max(0,radius));if(radius==0)return;int w=image.Width,h=image.Height;byte[] input=Pixels(image),temp=new byte[input.Length],output=new byte[input.Length];for(int y=0;y<h;y++)for(int c=0;c<4;c++){long sum=0;for(int x=-radius;x<=radius;x++)sum+=input[(y*w+Math.Max(0,Math.Min(w-1,x)))*4+c];for(int x=0;x<w;x++){temp[(y*w+x)*4+c]=(byte)(sum/(radius*2+1));sum-=input[(y*w+Math.Max(0,x-radius))*4+c];sum+=input[(y*w+Math.Min(w-1,x+radius+1))*4+c];}}for(int x=0;x<w;x++)for(int c=0;c<4;c++){long sum=0;for(int y=-radius;y<=radius;y++)sum+=temp[(Math.Max(0,Math.Min(h-1,y))*w+x)*4+c];for(int y=0;y<h;y++){output[(y*w+x)*4+c]=(byte)(sum/(radius*2+1));sum-=temp[(Math.Max(0,y-radius)*w+x)*4+c];sum+=temp[(Math.Min(h-1,y+radius+1)*w+x)*4+c];}}Put(image,output);}
  static void ApplyBlur(Bitmap image,GazeSettings s){if(s.blurType=="off"||s.blurAmount<=0)return;int radius=Math.Min(24,Math.Max(1,(int)(s.blurAmount/4)));if(s.blurType=="directional"||s.blurType=="motion"){byte[] input=Pixels(image),output=new byte[input.Length];int w=image.Width,h=image.Height;double angle=s.blurAngle*Math.PI/180;for(int y=0;y<h;y++)for(int x=0;x<w;x++)for(int c=0;c<4;c++){double sum=0;int n=0;for(int k=s.directionalBothSides?-radius:0;k<=radius;k++){int xx=Math.Max(0,Math.Min(w-1,x+(int)(k*Math.Cos(angle)))),yy=Math.Max(0,Math.Min(h-1,y+(int)(k*Math.Sin(angle))));sum+=input[(yy*w+xx)*4+c];n++;}output[(y*w+x)*4+c]=Byte(sum/n);}Put(image,output);return;}using(var blurred=(Bitmap)image.Clone()){Blur(blurred,radius);if(s.blurType=="gaussian"||s.blurType=="box"||s.blurType=="blur"){using(var g=Graphics.FromImage(image)){g.CompositingMode=CompositingMode.SourceCopy;g.DrawImageUnscaled(blurred,0,0);}return;}byte[] original=Pixels(image),soft=Pixels(blurred);int w=image.Width,h=image.Height;for(int y=0;y<h;y++)for(int x=0;x<w;x++){double amount=1;if(s.blurType=="tilt"||s.blurType=="tilt-shift")amount=Clamp((Math.Abs(y/(double)h-s.tiltPosition/100)-s.tiltFocus/200)/Math.Max(.01,s.tiltFeather/100));else if(s.blurType=="lens"||s.blurType=="radial")amount=Clamp((Math.Sqrt(Math.Pow(x/(double)w-s.blurCenterX/100,2)+Math.Pow(y/(double)h-s.blurCenterY/100,2))-s.lensFocus/200)*4);else if(s.blurType=="progressive"){amount=Clamp((y/(double)h-s.progressivePosition/100)/Math.Max(.01,1-s.progressivePosition/100));if(s.progressiveReverse)amount=1-amount;}int i=(y*w+x)*4;for(int c=0;c<4;c++)original[i+c]=Byte(original[i+c]*(1-amount)+soft[i+c]*amount);}Put(image,original);}}
